import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DCnq5n9u.js";import"./chunks/assets.Z1WblXMO.js";var i=JSON.parse(`{"title":"查看环境变量","description":"","frontmatter":{"version":"2.1.10"},"headers":[],"relativePath":"guide/feature/variables.md","filePath":"guide/feature/variables.md","lastUpdated":1788751487000}`),a={name:`guide/feature/variables.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n('<h1 id="查看环境变量" tabindex="-1">查看环境变量 <a class="header-anchor" href="#查看环境变量" aria-label="Permalink to “查看环境变量”">​</a></h1><h2 id="_1-jenkins-内置环境变量" tabindex="-1">1. Jenkins 内置环境变量 <a class="header-anchor" href="#_1-jenkins-内置环境变量" aria-label="Permalink to “1. Jenkins 内置环境变量”">​</a></h2><p>Jenkins 提供了内置环境变量页面，可用于查看当前实例支持的变量列表：</p><ul><li><code>https://[your-jenkins-host]/env-vars.html</code></li></ul><h2 id="_2-插件注入的环境变量" tabindex="-1">2. 插件注入的环境变量 <a class="header-anchor" href="#_2-插件注入的环境变量" aria-label="Permalink to “2. 插件注入的环境变量”">​</a></h2><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>这些变量<strong>只在 Freestyle 任务的标题与消息内容模板中可用</strong>。<code>Pipeline</code> 步骤的变量来自流水线上下文，插件不会向其中注入下面这些变量——在 <code>lark</code> / <code>dingTalk</code> / <code>wechatWork</code> 步骤里请改用 Jenkins 内置变量（<code>${JOB_NAME}</code>、<code>${BUILD_URL}</code> 等）或 <code>${currentBuild.xxx}</code>。</p></div><table tabindex="0"><thead><tr><th>名称</th><th>说明</th></tr></thead><tbody><tr><td><code>PROJECT_NAME</code></td><td>任务的完整显示名。文件夹下的任务形如 <code>Folder » Job</code>，<strong>不能用于拼接 URL</strong></td></tr><tr><td><code>PROJECT_URL</code></td><td>任务页面的绝对地址，带尾部 <code>/</code></td></tr><tr><td><code>JOB_NAME</code></td><td>本次构建的显示名，形如 <code>#42</code>。注意会覆盖同名的 Jenkins 内置变量，见下方说明</td></tr><tr><td><code>JOB_URL</code></td><td>本次构建的绝对地址，带尾部 <code>/</code>，可直接拼 <code>changes</code>、<code>console</code></td></tr><tr><td><code>JOB_DURATION</code></td><td>构建耗时（可读格式）</td></tr><tr><td><code>JOB_STATUS</code></td><td>构建状态，语言跟随该机器人的「消息语言」设置</td></tr><tr><td><code>EXECUTOR_NAME</code></td><td>构建执行人姓名</td></tr><tr><td><code>EXECUTOR_MOBILE</code></td><td>构建执行人手机号</td></tr><tr><td><code>EXECUTOR_OPENID</code></td><td>构建执行人 OpenID</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><code>JOB_NAME</code> 与 Jenkins 内置变量同名但含义不同：Jenkins 内置的 <code>JOB_NAME</code> 是任务路径（如 <code>folder/job</code>），而插件注入的是本次构建的显示名（如 <code>#42</code>），且插件的值会覆盖内置值。需要任务路径时请改用 <code>${PROJECT_NAME}</code>（显示名）或 <code>${PROJECT_URL}</code>（地址）。</p></div><p>拼接链接时优先使用 <code>PROJECT_URL</code> 和 <code>JOB_URL</code>，不要用 <code>${JENKINS_URL}/job/${PROJECT_NAME}/</code> 这类写法——<code>PROJECT_NAME</code> 含空格和 <code>»</code>，对文件夹下的任务会拼出错误地址。</p><h2 id="_3-用户属性扩展" tabindex="-1">3. 用户属性扩展 <a class="header-anchor" href="#_3-用户属性扩展" aria-label="Permalink to “3. 用户属性扩展”">​</a></h2><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>如需在 <strong>执行人</strong> 字段中实现 <code>@</code> 提醒效果，需要为 Jenkins 用户补充相关属性信息。可按以下路径进入用户设置页面：<code>Dashboard</code> -&gt; <code>Manage Jenkins</code> -&gt; <code>Users</code> -&gt; <code>用户设置</code></p></div><p><img src="/lark-notice-plugin-doc/assets/feq-user-attribute.DeAH0OZ9.png" alt="" width="1016" height="285"></p>',12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};